class Solution {
  public long countStableSubarrays(int[] capacity) {
    int n = capacity.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + capacity[i];
    java.util.HashMap<Integer, java.util.HashMap<Long, Integer>> seen = new java.util.HashMap<>();
    long total = 0;
    for (int r = 2; r < n; r++) {
      int l = r - 2;
      seen.computeIfAbsent(capacity[l], k -> new java.util.HashMap<>())
          .merge(pre[l + 1], 1, Integer::sum);
      java.util.HashMap<Long, Integer> byPre = seen.get(capacity[r]);
      if (byPre != null) total += byPre.getOrDefault(pre[r] - capacity[r], 0);
    }
    return total;
  }
}
